import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.EUByU7Iq.js";const p=JSON.parse('{"title":"第九章 饲养动物损害责任","description":"","frontmatter":{"title":"第九章 饲养动物损害责任","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/dijiuzhang：siyangdongwusunhaizeren.md","filePath":"blogs/CC/第九章：饲养动物损害责任.md"}'),i={name:"blogs/CC/dijiuzhang：siyangdongwusunhaizeren.md"};function n(h,a,l,s,d,_){return t(),r("div",null,[...a[0]||(a[0]=[o('<h3 id="第一千二百四十五条" tabindex="-1">第一千二百四十五条 <a class="header-anchor" href="#第一千二百四十五条" aria-label="Permalink to &quot;第一千二百四十五条&quot;">​</a></h3><p>饲养的动物造成他人损害的，动物饲养人或者管理人应当承担侵权责任；但是，能够证明损害是因被侵权人故意或者重大过失造成的，可以不承担或者减轻责任。</p><h3 id="第一千二百四十六条" tabindex="-1">第一千二百四十六条 <a class="header-anchor" href="#第一千二百四十六条" aria-label="Permalink to &quot;第一千二百四十六条&quot;">​</a></h3><p>违反管理规定，未对动物采取安全措施造成他人损害的，动物饲养人或者管理人应当承担侵权责任；但是，能够证明损害是因被侵权人故意造成的，可以减轻责任。</p><h3 id="第一千二百四十七条" tabindex="-1">第一千二百四十七条 <a class="header-anchor" href="#第一千二百四十七条" aria-label="Permalink to &quot;第一千二百四十七条&quot;">​</a></h3><p>禁止饲养的烈性犬等危险动物造成他人损害的，动物饲养人或者管理人应当承担侵权责任。</p><h3 id="第一千二百四十八条" tabindex="-1">第一千二百四十八条 <a class="header-anchor" href="#第一千二百四十八条" aria-label="Permalink to &quot;第一千二百四十八条&quot;">​</a></h3><p>动物园的动物造成他人损害的，动物园应当承担侵权责任；但是，能够证明尽到管理职责的，不承担侵权责任。</p><h3 id="第一千二百四十九条" tabindex="-1">第一千二百四十九条 <a class="header-anchor" href="#第一千二百四十九条" aria-label="Permalink to &quot;第一千二百四十九条&quot;">​</a></h3><p>遗弃、逃逸的动物在遗弃、逃逸期间造成他人损害的，由动物原饲养人或者管理人承担侵权责任。</p><h3 id="第一千二百五十条" tabindex="-1">第一千二百五十条 <a class="header-anchor" href="#第一千二百五十条" aria-label="Permalink to &quot;第一千二百五十条&quot;">​</a></h3><p>因第三人的过错致使动物造成他人损害的，被侵权人可以向动物饲养人或者管理人请求赔偿，也可以向第三人请求赔偿。动物饲养人或者管理人赔偿后，有权向第三人追偿。</p><h3 id="第一千二百五十一条" tabindex="-1">第一千二百五十一条 <a class="header-anchor" href="#第一千二百五十一条" aria-label="Permalink to &quot;第一千二百五十一条&quot;">​</a></h3><p>饲养动物应当遵守法律法规，尊重社会公德，不得妨碍他人生活。</p>',14)])])}const u=e(i,[["render",n]]);export{p as __pageData,u as default};
